import * as THREE from "three";
import type { MascotCharacter } from "./createMascotCharacter";

/** A stable look derived from an agent id. The same seed always rebuilds the same coworker. */
export interface CharacterRecipe {
  seed: string;
  skin: string;
  accent: string;
  body: 0 | 1 | 2 | 3;
  eyes: 0 | 1 | 2;
  accessory: 0 | 1 | 2 | 3;
  tall: number;
}

const SKINS = [
  "#5eead4",
  "#fbbf24",
  "#c4b5fd",
  "#fb7185",
  "#7dd3fc",
  "#bef264",
  "#fdba74",
  "#a5b4fc",
  "#f9a8d4",
  "#86efac",
];
const ACCENTS = [
  "#0f766e",
  "#b45309",
  "#6d28d9",
  "#be123c",
  "#0369a1",
  "#4d7c0f",
  "#c2410c",
  "#4338ca",
  "#9d174d",
  "#166534",
];

function hashSeed(seed: string) {
  let hash = 2166136261;
  for (const char of seed) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
  return hash >>> 0;
}

export function recipeFromSeed(seed: string): CharacterRecipe {
  const hash = hashSeed(seed || "trace");
  return {
    seed,
    skin: SKINS[hash % SKINS.length],
    accent: ACCENTS[(hash >>> 4) % ACCENTS.length],
    body: ((hash >>> 8) % 4) as CharacterRecipe["body"],
    eyes: ((hash >>> 12) % 3) as CharacterRecipe["eyes"],
    accessory: ((hash >>> 16) % 4) as CharacterRecipe["accessory"],
    tall: 0.92 + ((hash >>> 20) % 18) / 100,
  };
}

function material(color: string, roughness = 0.46) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness: 0.04 });
}

function addMesh(
  parent: THREE.Object3D,
  geometry: THREE.BufferGeometry,
  mat: THREE.Material,
  position: [number, number, number],
  scale: [number, number, number] = [1, 1, 1],
) {
  const mesh = new THREE.Mesh(geometry, mat);
  mesh.position.set(...position);
  mesh.scale.set(...scale);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}

/** Builds a unique coworker from a seed. Variants differ in body, eyes, accessory, and palette. */
export function createVariantCharacter(seed: string): MascotCharacter {
  const recipe = recipeFromSeed(seed);
  const group = new THREE.Group();
  group.name = `variant:${seed}`;
  const body = new THREE.Group();
  group.add(body);
  const skin = material(recipe.skin);
  const accent = material(recipe.accent, 0.38);
  const ink = material("#121816", 0.4);
  const white = material("#f4fff8", 0.3);
  const sphere = new THREE.SphereGeometry(1, 28, 20);

  const bodyScale: [number, number, number] =
    recipe.body === 0 ? [0.62, 0.7, 0.48]
    : recipe.body === 1 ? [0.5, 0.78, 0.46]
    : recipe.body === 2 ? [0.74, 0.56, 0.5]
    : [0.58, 0.72, 0.4];
  addMesh(body, sphere, skin, [0, 0.95, 0], bodyScale);

  const eyeY = 1.05 + (recipe.body === 2 ? -0.08 : 0.04);
  const eyeZ = 0.34 + bodyScale[2] * 0.15;
  const spacing = 0.16 + (recipe.eyes === 1 ? 0.04 : 0);
  const eyeScale: [number, number, number] =
    recipe.eyes === 0 ? [0.055, 0.08, 0.04]
    : recipe.eyes === 1 ? [0.07, 0.09, 0.045]
    : [0.06, 0.045, 0.04];
  for (const side of [-1, 1]) {
    addMesh(body, sphere, ink, [side * spacing, eyeY, eyeZ], eyeScale);
    addMesh(body, sphere, white, [side * spacing - 0.015, eyeY + 0.02, eyeZ + 0.03], [0.016, 0.02, 0.01]);
  }

  if (recipe.accessory === 0) {
    const stalk = new THREE.CylinderGeometry(0.02, 0.02, 0.28, 8);
    addMesh(body, stalk, accent, [0.12, 1.55, 0]);
    addMesh(body, sphere, accent, [0.12, 1.72, 0], [0.07, 0.07, 0.07]);
  } else if (recipe.accessory === 1) {
    const visor = new THREE.TorusGeometry(0.28, 0.028, 8, 24, Math.PI);
    const mesh = addMesh(body, visor, accent, [0, eyeY, eyeZ - 0.02]);
    mesh.rotation.z = Math.PI;
    mesh.rotation.x = 0.15;
  } else if (recipe.accessory === 2) {
    const collar = new THREE.TorusGeometry(0.34, 0.045, 8, 20);
    const mesh = addMesh(body, collar, accent, [0, 0.62, 0]);
    mesh.rotation.x = Math.PI / 2;
  } else {
    addMesh(body, new THREE.BoxGeometry(0.16, 0.12, 0.04), accent, [0.22, 0.9, eyeZ]);
  }

  const legs: THREE.Group[] = [];
  const arms: THREE.Group[] = [];
  for (const side of [-1, 1]) {
    const leg = new THREE.Group();
    leg.position.set(side * 0.22, 0.42, 0);
    group.add(leg);
    addMesh(leg, sphere, ink, [0, -0.14, 0], [0.055, 0.18, 0.055]);
    addMesh(leg, sphere, accent, [0, -0.32, 0.05], [0.12, 0.08, 0.18]);
    legs.push(leg);

    const arm = new THREE.Group();
    arm.position.set(side * 0.48, 0.95, 0);
    arm.rotation.z = side * 0.2;
    body.add(arm);
    addMesh(arm, sphere, skin, [side * 0.06, -0.12, 0], [0.08, 0.2, 0.08]);
    addMesh(arm, sphere, skin, [side * 0.08, -0.28, 0.01], [0.09, 0.09, 0.09]);
    arms.push(arm);
  }

  group.scale.setScalar(recipe.tall);

  return {
    group,
    update(timeSeconds, walking = 0, sitting = false, resting = false) {
      const amount = THREE.MathUtils.clamp(walking, 0, 1);
      const step = timeSeconds * 8.5;
      const stride = Math.sin(step) * amount;
      body.position.y = Math.abs(Math.cos(step)) * 0.045 * amount + Math.sin(timeSeconds * 2.2) * 0.012;
      body.rotation.z = stride * 0.04;
      legs[0].rotation.x = stride * 0.58;
      legs[1].rotation.x = -stride * 0.58;
      arms[0].rotation.x = -stride * 0.4;
      arms[1].rotation.x = stride * 0.4;
      if (sitting) {
        body.rotation.x = 0.08;
        legs[0].rotation.x = -1.35;
        legs[1].rotation.x = -1.35;
        const typing = resting ? 0 : Math.sin(timeSeconds * 14) * 0.08;
        arms[0].rotation.x = resting ? -0.25 : -1.1 + typing;
        arms[1].rotation.x = resting ? -0.25 : -1.1 - typing;
      } else {
        body.rotation.x = amount * 0.04;
      }
    },
    dispose() {
      const geometries = new Set<THREE.BufferGeometry>();
      const materials = new Set<THREE.Material>();
      group.traverse((object) => {
        if (!(object instanceof THREE.Mesh)) return;
        geometries.add(object.geometry);
        for (const mat of Array.isArray(object.material) ? object.material : [object.material]) materials.add(mat);
      });
      for (const geometry of geometries) geometry.dispose();
      for (const mat of materials) mat.dispose();
      group.removeFromParent();
    },
  };
}

import { readdir, readFile, realpath, stat } from "node:fs/promises";
import { homedir } from "node:os";
import path from "node:path";

const TITLE_LIMIT = 300;

function text(value, limit = TITLE_LIMIT) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (!trimmed || trimmed.length > limit || /[\r\n]/.test(trimmed)) return null;
  if (/(?:\/Users\/|\/home\/|[A-Z]:\\|~\/)/.test(trimmed)) return null;
  return trimmed;
}

function stamp(value, fallbackMs) {
  if (typeof value === "number" && Number.isFinite(value)) {
    const ms = value > 1e12 ? value : value * 1000;
    const date = new Date(ms);
    if (!Number.isNaN(date.getTime())) return date.toISOString();
  }
  if (typeof value === "string" && Number.isFinite(Date.parse(value))) return new Date(value).toISOString();
  return new Date(fallbackMs).toISOString();
}

function count(value) {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null;
}

async function readJson(file) {
  try {
    return JSON.parse(await readFile(file, "utf8"));
  } catch {
    return null;
  }
}

/** Read-only metadata from local Grok sessions. Conversation files are never opened. */
export async function readGrokSessions({
  grokHome = process.env.GROK_HOME ?? path.join(homedir(), ".grok"),
  project = process.env.DOTS_SESSION_CWD ?? process.env.TRACE_SESSION_CWD ?? process.cwd(),
  now = Date.now(),
} = {}) {
  const sessionsRoot = path.join(grokHome, "sessions");
  const root = await realpath(sessionsRoot);
  const wanted = project ? path.resolve(project) : "";
  const found = [];
  const groups = await readdir(root, { withFileTypes: true });
  for (const group of groups) {
    if (!group.isDirectory() || group.name.startsWith(".")) continue;
    const groupPath = path.join(root, group.name);
    let cwd = group.name;
    try { cwd = decodeURIComponent(group.name); } catch { /* Keep the directory name. */ }
    const marker = await readJson(path.join(groupPath, ".cwd"));
    if (typeof marker === "string" && marker.trim()) cwd = marker.trim();
    else {
      const markerFile = await readFile(path.join(groupPath, ".cwd"), "utf8").catch(() => "");
      if (markerFile.trim()) cwd = markerFile.trim();
    }
    if (wanted && path.resolve(cwd) !== wanted && path.basename(cwd) !== path.basename(wanted)) continue;
    const entries = await readdir(groupPath, { withFileTypes: true });
    for (const entry of entries) {
      if (!entry.isDirectory() || entry.name.startsWith(".")) continue;
      const dir = await realpath(path.join(groupPath, entry.name));
      if (!dir.startsWith(root + path.sep)) continue;
      const summary = await readJson(path.join(dir, "summary.json"));
      if (!summary || typeof summary !== "object") continue;
      const signals = (await readJson(path.join(dir, "signals.json"))) ?? {};
      const info = await stat(path.join(dir, "summary.json"));
      const updatedAt = stamp(
        summary.updated_at ?? summary.updatedAt ?? summary.updated ?? signals.updated_at ?? signals.updatedAt,
        info.mtimeMs,
      );
      const age = now - Date.parse(updatedAt);
      const ended = Boolean(summary.archived || summary.ended_at || summary.endedAt || summary.status === "completed" || summary.status === "idle");
      const status = ended ? "idle" : Number.isFinite(age) && age >= 0 && age < 5 * 60_000 ? "working" : Number.isFinite(age) ? "idle" : "unknown";
      const title = text(summary.title) ?? text(summary.summary) ?? text(summary.name) ?? "Session title unavailable";
      const contextUsed = count(signals.context_used ?? signals.contextUsed ?? signals.input_tokens);
      const contextWindow = count(signals.context_window ?? signals.contextWindow ?? signals.context_limit);
      found.push({
        id: entry.name,
        name: title,
        harness: "grok",
        model: text(summary.model, 80) ?? text(summary.model_id, 80) ?? text(summary.modelId, 80),
        status,
        task: title === "Session title unavailable" ? null : title,
        contextUsed: contextUsed !== null && contextWindow !== null ? contextUsed : null,
        contextWindow: contextUsed !== null && contextWindow !== null ? contextWindow : null,
        updatedAt,
        activityLabel: text(summary.activity, 160),
        parentId: text(summary.parent_session_id, 80) ?? text(summary.parentSessionId, 80),
      });
    }
  }
  found.sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt));
  const agents = found.slice(0, 50).map(({ parentId, ...agent }) => agent);
  const ids = new Set(agents.map((agent) => agent.id));
  const interactions = found
    .filter((agent) => agent.parentId && ids.has(agent.id) && ids.has(agent.parentId) && agent.parentId !== agent.id)
    .map((agent) => ({ fromId: agent.parentId, toId: agent.id, at: agent.updatedAt, kind: "delegation" }))
    .slice(0, 100);
  if (!agents.length) {
    throw new Error("No Grok sessions were found for this project. Start one here, or import a snapshot.");
  }
  return {
    version: 1,
    agents,
    interactions,
    project: path.basename(wanted || root),
    total: found.length,
    observedAt: new Date(now).toISOString(),
    source: "grok",
  };
}

"use client";

import type { ThreeEvent } from "@react-three/fiber";
import { useLayoutEffect, useMemo, useRef } from "react";
import * as THREE from "three";
import { SCALE } from "@/features/retro-office/core/constants";
import {
  getItemBaseSize,
  getItemRotationRadians,
  ITEM_FOOTPRINT,
  toWorld,
} from "@/features/retro-office/core/geometry";
import type { FurnitureItem } from "@/features/retro-office/core/types";

const furnitureTemplateCache = new Map<string, THREE.Group>();

type InstancedFurnitureMeshDef = {
  castShadow: boolean;
  geometry: THREE.BufferGeometry;
  material: THREE.Material;
  matrixWorld: THREE.Matrix4;
  receiveShadow: boolean;
};

function finish(mesh: THREE.Mesh) {
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function material(color: string, roughness = 0.62, metalness = 0.06, emissive?: string) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness,
    metalness,
    emissive: emissive ? new THREE.Color(emissive) : new THREE.Color("#000000"),
    emissiveIntensity: emissive ? 0.45 : 0,
  });
}

function box(
  parent: THREE.Object3D,
  size: [number, number, number],
  position: [number, number, number],
  color: string,
  roughness = 0.62,
) {
  const mesh = finish(new THREE.Mesh(new THREE.BoxGeometry(...size), material(color, roughness)));
  mesh.position.set(...position);
  parent.add(mesh);
  return mesh;
}

/** Original furniture, authored in office units and centered on the item footprint. */
function buildTemplate(itemType: string) {
  const cached = furnitureTemplateCache.get(itemType);
  if (cached) return cached;
  const group = new THREE.Group();
  const [footW, footD] = ITEM_FOOTPRINT[itemType] ?? [40, 40];
  const cx = footW * SCALE * 0.5;
  const cz = footD * SCALE * 0.5;
  const wood = "#4a4038";
  const ink = "#1c2622";

  if (itemType === "desk_cubicle" || itemType === "executive_desk") {
    box(group, [1.5, 0.07, 0.82], [cx, 0.74, cz], "#5c6b62");
    box(group, [1.42, 0.62, 0.06], [cx, 0.4, cz - 0.34], "#2e3b36");
    for (const [x, z] of [[-0.66, -0.32], [0.66, -0.32], [-0.66, 0.32], [0.66, 0.32]]) {
      box(group, [0.06, 0.7, 0.06], [cx + x, 0.35, cz + z], ink);
    }
  } else if (itemType === "chair") {
    box(group, [0.46, 0.07, 0.46], [cx, 0.46, cz], "#6b5344");
    box(group, [0.46, 0.42, 0.06], [cx, 0.7, cz + 0.2], "#6b5344");
    for (const x of [-0.18, 0.18]) box(group, [0.05, 0.42, 0.05], [cx + x, 0.22, cz], ink);
  } else if (itemType === "computer") {
    box(group, [0.42, 0.28, 0.04], [cx, 0.28, cz], "#101816");
    const screen = finish(new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.2, 0.02), material("#12352c", 0.4, 0.1, "#1f8f62")));
    screen.position.set(cx, 0.28, cz + 0.02);
    group.add(screen);
    box(group, [0.08, 0.12, 0.06], [cx, 0.08, cz], "#2a3330");
    box(group, [0.22, 0.02, 0.1], [cx, 0.02, cz + 0.06], "#2a3330");
  } else if (itemType === "bookshelf") {
    box(group, [0.7, 1.5, 0.28], [cx, 0.75, cz], wood);
    for (const y of [0.35, 0.75, 1.15]) box(group, [0.62, 0.04, 0.24], [cx, y, cz], "#2c241e");
    const spines = ["#3ecf8e", "#7dd3fc", "#fbbf24", "#fb7185"];
    spines.forEach((color, index) => box(group, [0.08, 0.28, 0.16], [cx - 0.22 + index * 0.14, 0.95, cz + 0.02], color));
  } else if (itemType === "plant") {
    box(group, [0.28, 0.24, 0.28], [cx, 0.14, cz], "#6b4a32");
    const leaves = finish(new THREE.Mesh(new THREE.SphereGeometry(0.28, 16, 12), material("#3d8f62", 0.7)));
    leaves.position.set(cx, 0.52, cz);
    leaves.scale.set(1, 0.8, 1);
    group.add(leaves);
  } else if (itemType === "lamp") {
    box(group, [0.28, 0.04, 0.28], [cx, 0.04, cz], "#3a342c");
    box(group, [0.04, 1.15, 0.04], [cx, 0.62, cz], "#c4b08a");
    const shade = finish(new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.22, 16), material("#f0c56a", 0.45, 0.05, "#e7a23a")));
    shade.position.set(cx, 1.22, cz);
    group.add(shade);
  } else if (itemType === "coffee_machine") {
    box(group, [0.32, 0.42, 0.28], [cx, 0.28, cz], "#d7c4a8");
    box(group, [0.1, 0.08, 0.08], [cx, 0.2, cz + 0.12], ink);
  } else if (itemType === "cabinet") {
    box(group, [1.3, 0.72, 0.4], [cx, 0.4, cz], "#334049");
    box(group, [0.02, 0.6, 0.02], [cx, 0.4, cz + 0.2], "#9bb0b8");
  } else {
    box(group, [0.6, 0.4, 0.4], [cx, 0.24, cz], "#3d4a44");
  }

  furnitureTemplateCache.set(itemType, group);
  return group;
}

const buildFurnitureItemMatrix = (item: FurnitureItem, itemType: string) => {
  const [wx, , wz] = toWorld(item.x, item.y);
  const yOffset = item.elevation ?? 0;
  const rotY = getItemRotationRadians(item);
  const { width, height } = getItemBaseSize(item);
  const pivotX = width * SCALE * 0.5;
  const pivotZ = height * SCALE * 0.5;
  const containerMatrix = new THREE.Matrix4().makeTranslation(wx, yOffset, wz);
  const pivotMatrix = new THREE.Matrix4().makeTranslation(pivotX, 0, pivotZ);
  const rotationMatrix = new THREE.Matrix4().makeRotationY(rotY);
  const unpivotMatrix = new THREE.Matrix4().makeTranslation(-pivotX, 0, -pivotZ);
  return containerMatrix.multiply(pivotMatrix).multiply(rotationMatrix).multiply(unpivotMatrix);
};

export function InstancedFurnitureItems({
  itemType,
  items,
  onItemClick,
}: {
  itemType: string;
  items: FurnitureItem[];
  onItemClick?: (itemUid: string) => void;
}) {
  const template = useMemo(() => buildTemplate(itemType), [itemType]);
  const meshRefs = useRef<Array<THREE.InstancedMesh | null>>([]);
  const meshDefs = useMemo<InstancedFurnitureMeshDef[]>(() => {
    template.updateMatrixWorld(true);
    const nextDefs: InstancedFurnitureMeshDef[] = [];
    template.traverse((child) => {
      if (!(child as THREE.Mesh).isMesh) return;
      const mesh = child as THREE.Mesh;
      nextDefs.push({
        castShadow: mesh.castShadow,
        geometry: mesh.geometry,
        material: mesh.material as THREE.Material,
        matrixWorld: mesh.matrixWorld.clone(),
        receiveShadow: mesh.receiveShadow,
      });
    });
    return nextDefs;
  }, [template]);
  const itemMatrices = useMemo(
    () => items.map((item) => buildFurnitureItemMatrix(item, itemType)),
    [itemType, items],
  );
  const itemUidByInstanceId = useMemo(() => items.map((item) => item._uid), [items]);
  const handleClick = useMemo(
    () =>
      onItemClick
        ? (event: ThreeEvent<MouseEvent>) => {
            event.stopPropagation();
            const instanceId = event.instanceId;
            if (typeof instanceId !== "number") return;
            const itemUid = itemUidByInstanceId[instanceId];
            if (itemUid) onItemClick(itemUid);
          }
        : undefined,
    [itemUidByInstanceId, onItemClick],
  );

  useLayoutEffect(() => {
    meshDefs.forEach((def, meshIndex) => {
      const instancedMesh = meshRefs.current[meshIndex];
      if (!instancedMesh) return;
      const worldMatrix = new THREE.Matrix4();
      for (let itemIndex = 0; itemIndex < itemMatrices.length; itemIndex += 1) {
        worldMatrix.multiplyMatrices(itemMatrices[itemIndex], def.matrixWorld);
        instancedMesh.setMatrixAt(itemIndex, worldMatrix);
      }
      instancedMesh.instanceMatrix.needsUpdate = true;
      instancedMesh.computeBoundingSphere();
    });
  }, [itemMatrices, meshDefs]);

  if (items.length === 0) return null;
  return (
    <>
      {meshDefs.map((def, meshIndex) => (
        <instancedMesh
          key={`${itemType}-${meshIndex}`}
          ref={(node) => {
            meshRefs.current[meshIndex] = node;
          }}
          args={[def.geometry, def.material, items.length]}
          castShadow={def.castShadow}
          receiveShadow={def.receiveShadow}
          onClick={handleClick}
        />
      ))}
    </>
  );
}

