/** Builds a coworker from a seed and the room's chosen cast. The same seed stays stable inside one cast. */
export function createVariantCharacter(seed: string, cast: CharacterCast = "person"): MascotCharacter {
  const recipe = recipeFromSeed(seed);
  const group = new THREE.Group();
  group.name = `variant:${seed}`;
  const body = new THREE.Group();
  group.add(body);
  const skin = material(recipe.skin);
  const accent = material(recipe.accent, 0.38);
  const ink = material("#121816", 0.4);
  const white = material("#f4fff8", 0.3);
  const sphere = new THREE.SphereGeometry(1, 28, 20);
  const box = new THREE.BoxGeometry(1, 1, 1);

  const headY = cast === "signal" ? 1.52 : cast === "field" ? 1.46 : 1.42;
  const torsoScale: [number, number, number] = cast === "signal" ? [0.34, 0.42, 0.22] : cast === "field" ? [0.5, 0.4, 0.3] : [0.4, 0.42, 0.26];
  addMesh(body, box, accent, [0, 0.5, 0], [0.36, 0.18, 0.24]);
  addMesh(body, box, skin, [0, 0.92, 0], torsoScale);
