/** Jev pauses at each showcase desk before walking to the next. */
export const JEV_DWELL_SECONDS = 1.45;
export const JEV_WALK_SECONDS = 5.55;
export const JEV_LEG_SECONDS = JEV_DWELL_SECONDS + JEV_WALK_SECONDS;

export function jevWalkPhase(elapsedSeconds: number, stopCount: number) {
  const cycle = JEV_LEG_SECONDS * stopCount;
  const wrapped = ((elapsedSeconds % cycle) + cycle) % cycle;
  const leg = Math.floor(wrapped / JEV_LEG_SECONDS);
  const phase = wrapped % JEV_LEG_SECONDS;
  const index = leg % stopCount;
  const dwell = phase < JEV_DWELL_SECONDS;
  const walkProgress = dwell ? 0 : (phase - JEV_DWELL_SECONDS) / JEV_WALK_SECONDS;
  return { index, leg, dwell, walkProgress, phase };
}

