import * as THREE from "three";
import type { CharacterCast } from "../../../socialRoom";
import type { CharacterKind } from "../../../types";
import {
  createMascotCharacter,
  MASCOT_KINDS,
  type MascotCharacter,
  type MascotKind,
} from "./createMascotCharacter";

export type { MascotCharacter };

/** Stable look derived from an agent id (mascot kind + height). */
export interface CharacterRecipe {
  seed: string;
  kind: MascotKind;
  skin: string;
  accent: string;
  tall: number;
}

const MASCOT_SKIN: Record<MascotKind, string> = {
  "blue-dot": "#20a9ff",
  "frog-dot": "#b6e645",
  "yellow-dot": "#ffd64a",
  "pink-dot": "#f344bc",
  "purple-dot": "#a365ed",
  lovable: "#f961aa",
};

function hashSeed(seed: string) {
  let hash = 2166136261;
  for (const char of seed) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
  return hash >>> 0;
}

export function mascotKindFromSeed(seed: string): MascotKind {
  return MASCOT_KINDS[hashSeed(seed || "trace") % MASCOT_KINDS.length];
}

export function resolveMascotKind(seed: string, kind?: CharacterKind): MascotKind {
  if (kind && MASCOT_KINDS.includes(kind as MascotKind)) return kind as MascotKind;
  return mascotKindFromSeed(seed);
}

export function recipeFromSeed(seed: string): CharacterRecipe {
  const kind = mascotKindFromSeed(seed);
  const hash = hashSeed(seed);
  return {
    seed,
    kind,
    skin: MASCOT_SKIN[kind],
    accent: MASCOT_SKIN[kind],
    tall: 0.98 + ((hash >>> 12) % 10) / 100,
  };
}

function material(color: string, roughness = 0.46) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness: 0.04 });
}

function applyCastShell(group: THREE.Group, cast: CharacterCast, recipe: CharacterRecipe) {
  if (cast === "person") return;
  const accent = material(recipe.accent, 0.38);
  const ink = material("#121816", 0.4);
  if (cast === "field") {
    group.scale.x *= 1.06;
    group.scale.z *= 1.04;
    const cap = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.1, 0.32), accent);
    cap.position.set(0.08, 1.55, 0.05);
    cap.castShadow = true;
    group.add(cap);
  } else if (cast === "signal") {
    group.scale.x *= 0.94;
    const visor = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.07, 0.06), ink);
    visor.position.set(0, 1.12, 0.34);
    visor.castShadow = true;
    group.add(visor);
  }
}

/** Builds a coworker from seed, room cast, and optional saved mascot kind. */
export function createVariantCharacter(
  seed: string,
  cast: CharacterCast = "person",
  kind?: CharacterKind,
): MascotCharacter {
  const recipe = recipeFromSeed(seed);
  const mascotKind = resolveMascotKind(seed, kind);
  const root = new THREE.Group();
  root.name = `variant:${seed}:${cast}`;
  const instance = createMascotCharacter(mascotKind);
  root.add(instance.group);
  instance.group.scale.setScalar(recipe.tall);
  applyCastShell(instance.group, cast, recipe);

  return {
    group: root,
    update: instance.update.bind(instance),
    dispose() {
      instance.dispose();
      root.removeFromParent();
    },
  };
}

