/** Which live sessions should become a Neatlogs span. Chat text is never included. */
export function sessionsToReport(seen, agents) {
  const next = new Map(seen);
  const report = [];
  for (const agent of agents ?? []) {
    if (!agent?.id || typeof agent.updatedAt !== "string") continue;
    const signature = `${agent.status}:${agent.updatedAt}`;
    if (next.get(agent.id) === signature) continue;
    next.set(agent.id, signature);
    if (agent.status === "working" || agent.status === "error" || agent.status === "blocked") {
      report.push({
        id: agent.id,
        harness: typeof agent.harness === "string" ? agent.harness : "local",
        status: agent.status,
        updatedAt: agent.updatedAt,
      });
    }
  }
  return { seen: next, report };
}

