function redact(text) {
  return text.replaceAll(key, "[redacted]");
}

async function post(body) {
  const payload = JSON.stringify(body);
  try {
    const res = await fetch("https://ingest.neatlogs.com/v1/trace", {
      method: "POST",
      headers: { "content-type": "application/json", "x-api-key": key },
      body: payload,
    });
    return { transport: "fetch", status: res.status, text: await res.text() };
  } catch (error) {
    const curl = spawnSync("curl", [
      "-sS",
      "-w",
      "\n%{http_code}",
      "-X",
      "POST",
      "https://ingest.neatlogs.com/v1/trace",
      "-H",
      "content-type: application/json",
      "-H",
      `x-api-key: ${key}`,
      "--data-binary",
      "@-",
    ], { input: payload, encoding: "utf8" });
    if (curl.status !== 0 && !curl.stdout) {
      throw error;
    }
    const lines = (curl.stdout || "").trimEnd().split("\n");
    const status = Number(lines.pop());
    return {
      transport: "curl",
      status,
      text: lines.join("\n"),
      fetchError: error instanceof Error ? error.message : String(error),
    };
  }
}

